// 4. GDPR Self-Service Portability & Erasure
// --------------------------------------------------------------------------
window.exportPersonalData = async function() {
  showToast('Generating complete GDPR machine-readable data archive...', 'info');
  window.announceToScreenReader('Exporting personal data bundle...');

  try {
    const res = await authFetch(`${API_BASE}/account/export`, { method: 'POST' });
    if (!res.ok) {
      const err = await res.json();
      showToast(`Export failed: ${err.detail || 'Server error'}`, 'error');
      return;
    }

    const data = await res.json();
    const jsonBlob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const downloadUrl = URL.createObjectURL(jsonBlob);
    const a = document.createElement('a');
    a.href = downloadUrl;
    a.download = `jobcopilot_personal_data_export_${data.user_id || 'user'}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(downloadUrl);

    showToast('GDPR Data Archive downloaded (.json)', 'success');
    window.announceToScreenReader('Personal data export downloaded successfully.');
  } catch (err) {
    showToast(`Export error: ${err.message}`, 'error');
  }
};

window.openDeleteAccountModal = function() {
  const modal = document.getElementById('modal-gdpr-delete');
  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
    const pwd = document.getElementById('delete-account-password');
    const chk = document.getElementById('delete-account-consent');
    if (pwd) pwd.value = '';
    if (chk) chk.checked = false;
  }
};

window.closeDeleteAccountModal = function() {
  const modal = document.getElementById('modal-gdpr-delete');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('active');
  }
};

window.executeAccountDeletion = async function() {
  const pwdInput = document.getElementById('delete-account-password');
  const chkInput = document.getElementById('delete-account-consent');
  const password = pwdInput ? pwdInput.value : '';
  const consented = chkInput ? chkInput.checked : false;

  if (!password) {
    showToast('Password confirmation is required to delete your account.', 'error');
    if (pwdInput) pwdInput.focus();
    return;
  }
  if (!consented) {
    showToast('Please check the confirmation box to authorize permanent deletion.', 'error');
    return;
  }

  try {
    const res = await authFetch(`${API_BASE}/account`, {
      method: 'DELETE',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ password })
    });

    if (!res.ok) {
      const err = await res.json();
      showToast(`Deletion failed: ${err.detail || 'Verification error'}`, 'error');
      return;
    }

    window.closeDeleteAccountModal();
    alert('Your account and all associated tenant records have been permanently erased under GDPR Article 17. Thank you for using JobCopilot.');
    localStorage.clear();
    sessionStorage.clear();
    window.location.href = '/';
  } catch (err) {
    showToast(`Erasure error: ${err.message}`, 'error');
  }
};

// --------------------------------------------------------------------------
// 5. PWA Offline Queue & Native Push Notifications
// --------------------------------------------------------------------------
window.initOfflineQueue = function() {
  if (window._offlineQueueInitialized) return; // avoid double-binding on re-login
  window._offlineQueueInitialized = true;
  const updateOfflineState = () => {
    const offlineBanner = document.getElementById('offline-banner');
    if (!navigator.onLine) {
      if (offlineBanner) offlineBanner.classList.add('active');
      window.announceToScreenReader('Network connection lost. Operating in offline mode.');
    } else {
      if (offlineBanner) offlineBanner.classList.remove('active');
      window.flushOfflineQueue();
    }
  };

  window.addEventListener('online', updateOfflineState);
  window.addEventListener('offline', updateOfflineState);
  updateOfflineState();
};

window.flushOfflineQueue = function() {
  const raw = localStorage.getItem('jobcopilot_offline_queue');
  if (!raw) return;
  try {
    const queue = JSON.parse(raw);
    if (Array.isArray(queue) && queue.length > 0) {
      showToast(`Connection restored: sync complete (${queue.length} offline items processed).`, 'success');
      localStorage.removeItem('jobcopilot_offline_queue');
      const countEl = document.getElementById('offline-queue-count');
      if (countEl) countEl.textContent = '0 items queued';
    }
  } catch (e) {
    localStorage.removeItem('jobcopilot_offline_queue');
  }
};

window.requestPushNotifications = async function() {
  if (!('Notification' in window)) {
    showToast('This browser does not support desktop/mobile push notifications.', 'info');
    return;
  }
  try {
    const perm = await Notification.requestPermission();
    if (perm === 'granted') {
      showToast('Push notifications enabled for JobCopilot!', 'success');
      new Notification('JobCopilot Notifications Enabled', {
        body: 'You will receive real-time alerts for HITL CAPTCHA challenges and recruiter interviews.',
        icon: '/icons/icon-192.png'
      });
    } else {
      showToast(`Notification permission: ${perm}`, 'info');
    }
  } catch (err) {
    showToast(`Notification error: ${err.message}`, 'error');
  }
};

// --------------------------------------------------------------------------
// 6. WCAG 2.1 AA Keyboard Navigation & Focus Traps
// --------------------------------------------------------------------------
let _modalLastFocus = null;

function getModalFocusableElements(container) {
  if (!container) return [];
  const selector = 'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';
  return Array.from(container.querySelectorAll(selector))
    .filter(el => el.offsetWidth > 0 || el.offsetHeight > 0 || el.getClientRects().length > 0);
}

// Moves focus into a modal on open and remembers the trigger element to restore focus on close.
window.openModal = function(modalIdOrEl) {
  const modal = typeof modalIdOrEl === 'string' ? document.getElementById(modalIdOrEl) : modalIdOrEl;
  if (!modal) return;
  _modalLastFocus = document.activeElement;
  modal.classList.add('active');
  if (modal.style.display === 'none') modal.style.display = 'flex';

  requestAnimationFrame(() => {
    const focusables = getModalFocusableElements(modal);
    if (focusables.length > 0) {
      focusables[0].focus();
    } else {
      modal.setAttribute('tabindex', '-1');
      modal.focus();
    }
  });
};

// Closes a modal and restores focus to whatever triggered it.
window.closeModal = function(modalIdOrEl) {
  const modal = typeof modalIdOrEl === 'string' ? document.getElementById(modalIdOrEl) : modalIdOrEl;
  if (!modal) return;
  modal.classList.remove('active');
  if (modal.style.display !== '') modal.style.display = 'none';

  if (_modalLastFocus && typeof _modalLastFocus.focus === 'function') {
    try { _modalLastFocus.focus(); } catch (_) {}
    _modalLastFocus = null;
  }
};

document.addEventListener('keydown', (event) => {
  // Tab key focus trap inside the active modal dialog
  if (event.key === 'Tab') {
    const activeDialog = document.querySelector(
      '.modal-overlay.active, .glass-booth-overlay.active, [role="dialog"].active, [role="dialog"][style*="display: flex"], [role="dialog"][style*="display: block"]'
    );
    if (activeDialog) {
      const focusables = getModalFocusableElements(activeDialog);
      if (focusables.length > 0) {
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (event.shiftKey) {
          if (document.activeElement === first || !activeDialog.contains(document.activeElement)) {
            event.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last || !activeDialog.contains(document.activeElement)) {
            event.preventDefault();
            first.focus();
          }
        }
      }
    }
  }

  // Escape key closes active modal dialogs or dropdowns
  if (event.key === 'Escape') {
    window.toggleWorkspaceDropdown(false);

    const activeModals = [
      'modal-job-details',
      'modal-add-slot',
      'modal-create-org',
      'modal-manage-org',
      'modal-proration-preview',
      'modal-gdpr-delete',
      'modal-held-applications',
      'modal-log-call',
      'hitl-modal',
      'outreach-modal',
      'interview-invite-modal',
      'glass-booth-modal',
      'modal-install-app'
    ];

    activeModals.forEach(id => {
      const el = document.getElementById(id);
      if (el && (el.classList.contains('active') || el.style.display === 'flex' || el.style.display === 'block')) {
        window.closeModal(el);
      }
    });

    if (typeof window.toggleCmdPalette === 'function') {
      window.toggleCmdPalette(false);
    }
  }
});

// Close a modal when clicking directly on its backdrop overlay
document.addEventListener('click', (event) => {
  if (event.target && event.target.classList && event.target.classList.contains('modal-overlay')) {
    window.closeModal(event.target);
  }
});

// Fallback: move focus into any dialog activated by code that doesn't call window.openModal directly.
if (typeof MutationObserver !== 'undefined') {
  const modalObserver = new MutationObserver((mutations) => {
    for (const m of mutations) {
      if (m.type === 'attributes' && (m.attributeName === 'class' || m.attributeName === 'style')) {
        const target = m.target;
        if (target && (target.classList.contains('modal-overlay') || target.classList.contains('glass-booth-overlay') || target.getAttribute('role') === 'dialog')) {
          const isActive = target.classList.contains('active') || (target.style.display !== 'none' && target.style.display !== '');
          if (isActive && !target.contains(document.activeElement)) {
            if (!_modalLastFocus) _modalLastFocus = document.activeElement;
            requestAnimationFrame(() => {
              const focusables = getModalFocusableElements(target);
              if (focusables.length > 0) focusables[0].focus();
            });
          }
        }
      }
    }
  });
  modalObserver.observe(document.body, { subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
}

// ==========================================================================
// Initialization on Load
// ==========================================================================
document.addEventListener('DOMContentLoaded', () => {
  // Restore connected portals from localStorage if available
  try {
    const savedPortals = localStorage.getItem('jobcopilot_connected_portals');
    if (savedPortals) {
      state.connectedPortals = Object.assign(state.connectedPortals, JSON.parse(savedPortals));
    }
  } catch (_) {}

  const token = localStorage.getItem('jobcopilot_access_token');
  const portalsConfigured = localStorage.getItem('jobcopilot_portals_configured') === 'true';

  // Restore saved candidate display name
  const savedCandidateName = localStorage.getItem('jobcopilot_user_name');
  if (savedCandidateName) {
    if (els.userDisplayName) els.userDisplayName.textContent = savedCandidateName;
    if (state.currentUser) state.currentUser.full_name = savedCandidateName;
  }

  // Bind Enter key and input clearing for Login email
  const loginEmailInput = document.getElementById('login-email-input');
  if (loginEmailInput) {
    loginEmailInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        window.loginWithGoogle();
      }
    });
    loginEmailInput.addEventListener('input', () => {
      const errEl = document.getElementById('login-email-error');
      if (errEl) errEl.style.display = 'none';
    });
  }
  const loginForm = document.getElementById('login-form');
  if (loginForm) {
    loginForm.addEventListener('submit', (e) => {
      e.preventDefault();
      window.loginWithGoogle();
    });
  }

  // Wire up real Google Sign-In (and apply production gating of the demo path).
  window.initGoogleSignIn();

  if (!token) {
    // No auth — show login gate, skip all data fetches
    window.switchTab('login');
    return;
  }

  // Authenticated — initialize data layer
  initWebSocket();
  fetchJobsList();
  fetchFunnelMetrics();
  fetchVaultEntries();
  fetchHeldApplications();
  updateSalaryEquivalents(15);
  populateMockQuestionsDropdown();
  window.checkAdminStatus();
  window.loadUserWorkspaces();
  window.initOfflineQueue();

  if (!portalsConfigured) {
    // Authenticated but portals not yet configured — show portal screen
    window.switchTab('connect-portals');
    renderPortalCards();
  } else {
    // Fully onboarded — go to requested view or pipeline
    const initialView = window.location.hash ? window.location.hash.replace('#', '') : 'pipeline';
    if (initialView === 'login' || initialView === 'connect-portals') {
      window.switchTab('pipeline');
    } else {
      window.switchTab(initialView);
    }
    renderPortalCards();
  }
});

